function P(u){let r=u.puntos;if(!r||r.length<2)return g("Se necesitan al menos 2 puntos para ajustar una recta.");if(r.some(n=>!Number.isFinite(n.x)||!Number.isFinite(n.y)))return g("Todos los puntos deben tener x e y num\xE9ricos.");let e=r.length,s=l(r,n=>n.x),t=l(r,n=>n.y),o=l(r,n=>n.x*n.y),a=l(r,n=>n.x*n.x),x=l(r,n=>n.y*n.y),m=e*a-s*s;if(Math.abs(m)<1e-12)return g("Todas las x son iguales: con esos datos no se puede ajustar una recta (no hay forma de saber c\xF3mo cambia y).");let i=(e*o-s*t)/m,d=(t-i*s)/e,Y=s/e,E=t/e,f=p(e,s,t,o,a,x),C=f*f,F=r.reduce((n,c)=>{let b=d+i*c.x;return n+(c.y-b)*(c.y-b)},0),R=e>2?Math.sqrt(F/(e-2)):0,h=r.map((n,c)=>{let b=d+i*n.x;return{i:c+1,xi:n.x,yi:n.y,x2:n.x*n.x,xy:n.x*n.y,yhat:b,residuo:n.y-b}});h.push({i:"\u03A3",xi:s,yi:t,x2:a,xy:o,yhat:"",residuo:""});let y=u.evaluarEn,X=y!==void 0&&Number.isFinite(y);return{filas:h,n:e,sumX:s,sumY:t,sumXY:o,sumX2:a,mediaX:Y,mediaY:E,a0:d,a1:i,r:f,r2:C,errorEstandar:R,evaluadoEn:X?y:void 0,prediccion:X?d+i*y:void 0,recta:N(d,i)}}function l(u,r){return u.reduce((e,s)=>e+r(s),0)}function p(u,r,e,s,t,o){let a=u*s-r*e,x=u*t-r*r,m=u*o-e*e;return x<=0||m<=0?0:a/Math.sqrt(x*m)}function N(u,r){let e=r<0?"\u2212":"+";return`y = ${M(u)} ${e} ${M(Math.abs(r))}\xB7x`}function g(u){return{filas:[],n:0,sumX:0,sumY:0,sumXY:0,sumX2:0,mediaX:0,mediaY:0,a0:0,a1:0,r:0,r2:0,errorEstandar:0,recta:"",mensaje:u}}function M(u){return Number.isInteger(u)?String(u):u.toFixed(6).replace(/\.?0+$/,"")}export{P as a};
